    blogId: "ndis-jobs-australia-disability-support-worker-2026",
    title: "NDIS Jobs in Australia 2026: How to Become a Disability Support Worker and What You'll Earn",
    image: blog_1,
    insideimage: insideimage21,
    outsideimage: outsideimage21,
    author: "John Doe",
